"""AI layer: emergency pre-check, Claude API call, and labelled demo mode.

Every reply carries a `source` so the UI can say honestly where it came from:
  "emergency" - fixed safety message (no model call)
  "live"      - generated by the Claude API
  "demo"      - canned demo response (NOT generated by an AI model)
  "error"     - API unavailable; fixed fallback message
"""
import logging
import re
from pathlib import Path

from flask import current_app

logger = logging.getLogger(__name__)

PROMPT_PATH = Path(__file__).resolve().parent.parent / "prompts" / "system_prompt.txt"

DISCLAIMER = (
    "MediAssist AI shares general information only and is not a substitute for "
    "a qualified healthcare professional."
)

EMERGENCY_REPLY = (
    "This could be an emergency. Please contact your local emergency services "
    "(for example 112 in India, 911 in the US, 999 in the UK) or go to the nearest "
    "emergency department right now. If you are thinking about harming yourself, "
    "please call your local emergency number or a crisis line immediately and tell "
    "someone you trust.\n\nI can't assess symptoms or provide medical care here."
)

FALLBACK_REPLY = (
    "Sorry, I'm having trouble answering right now. Please try again in a moment, "
    "or contact the clinic directly. If this is urgent or an emergency, contact "
    "your local emergency services."
)

_EMERGENCY_PATTERNS = [
    r"chest pain", r"pain in (my )?chest", r"heart attack",
    r"(can'?t|cannot|can not|hard to|trouble|difficulty) breath",
    r"short(ness)? of breath", r"not breathing", r"stroke",
    r"face (is )?droop", r"slurred speech", r"unconscious", r"passed out",
    r"won'?t wake", r"severe bleeding", r"bleeding (heavily|a lot|won'?t stop)",
    r"anaphyla", r"throat (is )?(closing|swelling)", r"overdos",
    r"seizure", r"suicid", r"kill myself", r"end my life", r"want to die",
    r"self[- ]?harm", r"hurt myself", r"poison",
]
_EMERGENCY_RE = re.compile("|".join(_EMERGENCY_PATTERNS), re.IGNORECASE)


def load_system_prompt() -> str:
    text = PROMPT_PATH.read_text(encoding="utf-8")
    return "\n".join(l for l in text.splitlines() if not l.startswith("# ")).strip()


def is_emergency(text: str) -> bool:
    return bool(_EMERGENCY_RE.search(text))


def is_demo_mode() -> bool:
    return not current_app.config.get("ANTHROPIC_API_KEY")


_DEMO_RULES = [
    (r"hour|open|close|when are you",
     "The demo clinic is open Monday-Friday 09:00-17:00 and Saturday 09:00-13:00, closed Sunday. (Fictional demo data.)"),
    (r"service|offer|what do you do",
     "The demo clinic lists general consultation, vaccination, routine health check-ups, blood pressure monitoring and nutrition counselling. (Fictional demo data.)"),
    (r"appointment|book|schedule|request",
     "You can submit an appointment request using the form on the Appointment page with your name, email, preferred date and reason. "
     "It is only a request until the clinic confirms it by email."),
    (r"medic|dose|dosage|prescri|tablet|pill|antibiotic",
     "I can't recommend, prescribe or change medicines or doses. Please speak with your doctor or pharmacist about medication."),
    (r"fever|cough|cold|flu|headache|pain|symptom|rash|diagnos",
     "I can't diagnose conditions. General information: rest and fluids help many minor illnesses, but if symptoms are severe, "
     "persistent or worrying, please contact a qualified healthcare professional."),
    (r"vaccin|immuni",
     "Vaccines train the immune system to recognise specific germs. Ask the clinic or your doctor which vaccines are suitable for you."),
]
_DEMO_DEFAULT = (
    "I can help with clinic services, appointment requests and general health information. "
    "Try asking about clinic hours, services, or how to request an appointment."
)


def demo_reply(text: str) -> str:
    for pattern, reply in _DEMO_RULES:
        if re.search(pattern, text, re.IGNORECASE):
            return reply
    return _DEMO_DEFAULT


def _call_claude(messages: list[dict]) -> str:
    """Single place that talks to the Anthropic SDK (easy to mock in tests)."""
    import anthropic

    client = anthropic.Anthropic(
        api_key=current_app.config["ANTHROPIC_API_KEY"],
        timeout=current_app.config["ANTHROPIC_TIMEOUT"],
    )
    resp = client.messages.create(
        model=current_app.config["ANTHROPIC_MODEL"],
        max_tokens=current_app.config["ANTHROPIC_MAX_TOKENS"],
        system=load_system_prompt(),
        messages=messages,
    )
    return "".join(b.text for b in resp.content if getattr(b, "type", "") == "text").strip()


def get_reply(messages: list[dict]) -> dict:
    """Return {"reply": str, "source": str, "disclaimer": str}."""
    last_user = messages[-1]["content"]

    if is_emergency(last_user):
        return {"reply": EMERGENCY_REPLY, "source": "emergency", "disclaimer": DISCLAIMER}

    if is_demo_mode():
        return {"reply": demo_reply(last_user), "source": "demo", "disclaimer": DISCLAIMER}

    try:
        text = _call_claude(messages)
        if not text:
            raise ValueError("empty model response")
        return {"reply": text, "source": "live", "disclaimer": DISCLAIMER}
    except Exception:  # noqa: BLE001 - never leak details to the browser
        logger.exception("Claude API call failed")
        return {"reply": FALLBACK_REPLY, "source": "error", "disclaimer": DISCLAIMER}
